146→    const version = getVersion();
147→    logger.info(`Fetch Bridge ${version} starting...`);
148→
149→    // Start status API first so TUI can configure missing env in setup mode.
150→    startStatusServer();
151→    setWhatsAppControlCallbacks({
152→      start: requestBridgeStart,
153→      restart: restartBridge,
154→    });
155→
156→    if (!workflowInitialized) {
157→      await getWorkflowManager();
158→      workflowInitialized = true;
159→    }
160→
161→    // Stay alive in setup mode; start WhatsApp only when explicitly requested.
162→    updateStatus({ state: 'disconnected', lastError: 'WhatsApp not started. Open Setup WhatsApp to begin pairing.' });
