175→    shuttingDown = true;
176→    logger.info(`🛑 Received ${signal}, shutting down gracefully...`);
177→
178→    try {
179→      clearBootstrapTimer();
180→
181→      // 1. Kill any running harness child processes
182→      const { getHarnessPool } = await import('./harness/pool.js');
183→      try {
184→        const pool = getHarnessPool();
