194→        await activeBridge.destroy();
195→        activeBridge = null;
196→      }
197→
198→      // 4. Flush & close SQLite databases
199→      try { getSessionStore().close(); } catch { /* may not be initialized */ }
200→      try { getTaskStore().close(); } catch { /* may not be initialized */ }
201→
202→      // 5. Shutdown file watchers and manager-owned resources
203→      try { await getSkillManager().shutdown(); } catch { /* may not be initialized */ }
204→      try { getIdentityManager().shutdown(); } catch { /* may not be initialized */ }
205→      try { await getToolRegistry().shutdown(); } catch { /* may not be initialized */ }
