226→      logger.error('Uncaught exception - exiting', { message: error.message, stack: error.stack });
227→      exit(1);
228→    });
229→
230→    process.on('SIGINT', () => { void shutdown('SIGINT'); });
231→    process.on('SIGTERM', () => { void shutdown('SIGTERM'); });
232→  };
233→
234→  return { main, shutdown, registerProcessHandlers };
235→}
